async function stop(child){if(!child||child.exitCode!==null||child.signalCode!==null)return;child.kill('SIGTERM');await Promise.race([once(child,'exit'),sleep(5000)]);if(child.exitCode===null&&child.signalCode===null){child.kill('SIGKILL');await once(child,'exit');}}
async function cleanup(){if(cleaning)return;cleaning=true;await browser?.close().catch(()=>{});for(const child of [...children].reverse())await stop(child);provider?.closeAllConnections();if(provider?.listening)await new Promise(r=>provider.close(r));await pool?.end();}
process.once('SIGTERM',()=>void cleanup().finally(()=>process.exit(1)));process.once('SIGINT',()=>void cleanup().finally(()=>process.exit(1)));
function start(label,args,env,cwd=serverRoot){const log=fs.openSync(path.join(root,`${label}.log`),'a',0o600);const child=spawn(args[0],args.slice(1),{cwd,env,stdio:['ignore',log,log]});children.push(child);return child;}
async function port(){const s=http.createServer();s.listen(0,'127.0.0.1');await once(s,'listening');const p=s.address().port;await new Promise(r=>s.close(r));return p;}
async function ready(url,child){for(let i=0;i<150;i++){if(child.exitCode!==null)throw new Error(`Owned service exited (${child.exitCode}) before ${url}`);try{const r=await fetch(url,{signal:AbortSignal.timeout(1000)});if(r.status<500)return;}catch{}await sleep(100);}throw new Error('Owned service readiness timeout');}
