   else answer={text:'test durable answer',actions:text.includes('test_propose_feeding')?[{actionId:randomUUID(),entityType:'feeding',operation:'create',summary:'test formula 90ml',payload:{feedingType:'formula',amountMl:'90',occurredAt:'2026-09-15T03:00:00Z'}}]:[]};
