 const baseEnv={...process.env,NODE_ENV:'test',DATABASE_URL:database,REDIS_URL:redis,JWT_SECRET:'test_crossrepo_jwt_secret_minimum_32_chars!',S3_BUCKET:bucket,S3_ENDPOINT:object,S3_REGION:'us-east-1',S3_ACCESS_KEY_ID:key,S3_SECRET_ACCESS_KEY:secret,AWS_ACCESS_KEY_ID:key,AWS_SECRET_ACCESS_KEY:secret,AWS_EC2_METADATA_DISABLED:'true',GROWDESK_AI_PROVIDER:'openai-compatible',GROWDESK_AI_BASE_URL:providerUrl,GROWDESK_AI_API_KEY:'test_local_provider_key',GROWDESK_AI_MODEL:'test_model',GROWDESK_AUDIO_BASE_URL:providerUrl,GROWDESK_AUDIO_API_KEY:'test_local_provider_key',GROWDESK_AUDIO_MODEL:'test_audio_model',GROWDESK_TASK_QUEUE:`test-${randomUUID()}`,GROWDESK_WORKER_CONCURRENCY:'2'};
 const launchApi=()=>start('api',[process.execPath,'apps/api/dist/server.js'],{...baseEnv,HOST:'127.0.0.1',PORT:String(apiPort)});
 let apiChild=launchApi();await ready(api+'/health/live',apiChild);
 const launchWorker=()=>start('worker',[process.execPath,'apps/worker/dist/main.js'],baseEnv);
