 const launchWeb=()=>start('web',[process.execPath,'.next/standalone/server.js'],{...baseEnv,NODE_ENV:'production',NEXT_TELEMETRY_DISABLED:'1',HOSTNAME:'127.0.0.1',PORT:'3089',GROWDESK_ENABLED:'true',GROWDESK_API_URL:api,GROWDESK_WEB_ORIGIN:origin,DATABASE_URL:'file:./dev_test.db'},web);
 let webChild=launchWeb();await ready(origin+'/api/auth/me',webChild);
 async function apiCall(endpoint,body,token,method=body?'POST':'GET'){const response=await fetch(api+endpoint,{method,headers:{'content-type':'application/json',...(token?{authorization:`Bearer ${token}`}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(10000)});const json=await response.json();assert.ok(response.ok,`${endpoint}: ${response.status} ${JSON.stringify(json)}`);return json.data;}
 async function tenant(){const username=`test_browser_${randomUUID().slice(0,20)}`,password='Test_browser_password_123!';const data=await apiCall('/api/v1/auth/register',{username,password,displayName:'test_browser_user'});const family=(await apiCall('/api/v1/families',null,data.accessToken))[0];const baby=await apiCall(`/api/v1/families/${family.id}/babies`,{name:'test_browser_baby',birthDate:'2026-01-01',gender:'other'},data.accessToken);return{username,password,userId:data.user.id,token:data.accessToken,babyId:baby.id,familyId:family.id};}
 const a=await tenant(),b=await tenant();
 browser=await chromium.launch({executablePath:process.env.CHROMIUM_BINARY||'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--single-process','--no-zygote']});
 async function pageFor(tenant){const context=await browser.newContext({serviceWorkers:'block'});await context.route('**/*',route=>{const url=new URL(route.request().url());return ['127.0.0.1','localhost'].includes(url.hostname)||url.protocol==='data:'?route.continue():route.abort();});const page=await context.newPage();await page.goto(origin+'/login');await page.getByPlaceholder('请输入用户名').fill(tenant.username);await page.getByPlaceholder('请输入密码').fill(tenant.password);await page.locator('button[type=submit]').click();await page.waitForURL(origin+'/',{timeout:20000});return page;}
