 const call=(page,path,body,method)=>page.evaluate(async({path,body,method})=>{const response=await fetch(path,{method:method||(body?'POST':'GET'),headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});const text=await response.text();let data;try{data=JSON.parse(text);}catch{data=text;}return{status:response.status,data};},{path,body,method});
 await scenario('real browser login, secure session cookie, refresh and selected baby',async()=>{const me=await call(page,'/api/auth/me');assert.equal(me.status,200);assert.equal(me.data.user.id,a.userId);assert.ok((await page.context().cookies()).some(c=>c.name==='__Host-growdesk_web'&&c.secure&&c.httpOnly));await page.reload();assert.equal((await call(page,'/api/auth/me')).data.user.id,a.userId);});
