   const sent=await call(page,'/api/ai/chat',{babyId:a.babyId,contextType:'general',clientMessageId:randomUUID(),messages:[{role:'user',content:'test_query'}]});assert.equal(sent.status,200,JSON.stringify(sent));const frames=sent.data.split('\n').filter(l=>l.startsWith('data: {')).map(l=>JSON.parse(l.slice(6)));sid=frames.find(f=>f.session).session.id;assert.ok(frames.some(f=>f.text==='test durable answer'),JSON.stringify(frames));
